import com.sap.it.api.mapping.*;// Extracts the segment after the last underscore (_) from the given string.// For example, input: "GUY_RBGLGYGG" -> output: "RBGLGYGG"def String customFunc(String BankNumber){    if (BankNumber == null || BankNumber.trim() == "") {        return ""    }    // Split the string by underscore and return the last segment    return BankNumber.tokenize('_').last()}